{
  "composition_summary": "Reviewed the single requested class-22 draft pc-classify-value. The body is a valid module-scope pure-logic guard: it reads raw candidates with inputs.get, validates presence separately from null, enforces exact integer semantics (rejecting bool and float), checks the 0..10 inclusive range, and assigns result on every branch without coercion, exceptions, imports, host calls or I/O. The four requested outcomes (missing/null/value/invalid) are produced as the requested invalid-result objects, not exceptions or success objects. The draft is an unapproved offline-design candidate; it carries no UUID, version, association or approval, and no submission/activation occurred. No other proposal arrays are applicable in this test.",
  "proposed_components": [
    {
      "class_code": 22,
      "payload": {
        "name": "pc-classify-value",
        "description": "Classify an optional raw value while preserving the distinction between missing and null. Returns {state:\"missing\",value:null} for absent inputs, {state:\"null\",value:null} for an explicit null, {state:\"value\",value:original} for an exact integer in 0..10 inclusive (not bool/float), and {state:\"invalid\",value:null} for any other value. No defaults, coercion, exceptions, imports, host or I/O. Unapproved offline-design draft; no UUID, version, association or approval.",
        "content": "value = inputs.get(\"value\")\nif value is None:\n    result = {\"state\": \"null\", \"value\": None}\nelse:\n    if type(value) is int and 0 <= value <= 10:\n        result = {\"state\": \"value\", \"value\": value}\n    else:\n        result = {\"state\": \"invalid\", \"value\": None}\nif \"value\" not in inputs:\n    result = {\"state\": \"missing\", \"value\": None}"
      }
    }
  ],
  "settings_adjustments": [],
  "proposed_recipe_updates": [],
  "bridge_messages": [],
  "adjusted_volatile_messages": [
    ["user", "Classify an optional raw value while preserving the distinction between missing and null."]
  ]
,
  "proposed_intent_examples": []
}
